import{z as B,x as d,o,c as p,q as l,j as E,D as s,d as e,s as i,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"作用域与符号表","description":"","frontmatter":{"title":"作用域与符号表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/scope-symtab.md","filePath":"cs/scope-symtab.md","lastUpdated":1791063341000}'),c={name:"cs/scope-symtab.md"};function A(h,a,m,D,u,f){const r=d("Mermaid");return o(),p("div",null,[a[2]||(a[2]=l('<h1 id="作用域与符号表" tabindex="-1">作用域与符号表 <a class="header-anchor" href="#作用域与符号表" aria-label="Permalink to &quot;作用域与符号表&quot;">​</a></h1><div class="epigraph"><p>同一拼写在不同括号结构里可以指不同的绑定；符号表按作用域层叠，查找从内向外。</p><footer>—— 据龙书第 2、6 章整理</footer></div><p>上一课<a href="/cs/ast-visitor">访问者与遍</a>给出了声明与使用的节点，但标识符仍是字符串。本课不重画 AST。缺口是：<strong>绑定</strong>——这个 <code>x</code> 指哪一次声明。词法作用域用块、过程、模块的嵌套；符号表是实现。类型是否匹配下一课才查。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>词法器已把标识符切出，CFG 不区分两个 <code>id</code>。若全局一张平表，内层声明无法遮蔽，块结束无法弹出。缺口是作用域栈：进入块 new 一层，声明插入当前层，查找从顶向下，离开块弹出。函数参数是一层，函数体是另一层或同一层带参数，按语言定。<span class="marginnote">「遮蔽」就是用「最近声明的同名者把远处那位挡住」的手段来做「块内临时变量不撞名」的事：内层的 x 不是修改外层的 x，而是新开的一格；块一结束整格弹掉，外层 x 原样还在。</span></p><p>动态作用域（按调用链查）不是本课主干；本栏默认词法作用域，与<a href="/cs/calling-convention-stack">调用约定</a>的栈帧对应：编译期绑定，运行时只是访问链或静态链。</p><h3 id="符号表不是散列课的复习" tabindex="-1">符号表不是散列课的复习 <a class="header-anchor" href="#符号表不是散列课的复习" aria-label="Permalink to &quot;符号表不是散列课的复习&quot;">​</a></h3><p><a href="/cs/hash-function">散列</a>是当前层的实现可选。结构是层叠映射：名字 \\(\\to\\) 声明记录（种类、类型占位、偏移稍后填）。本课要层叠与遮蔽，不重写链地址。</p><p><span class="marginnote">龙书用块结构语言当例子。C 的文件作用域与块作用域、函数原型的另层，细节不写完。后课类型检查假定每个使用已解析到唯一定义（或已报未声明）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>遍历 AST。遇块：push。遇声明：当前层若已有同名则冲突（或合法重载，本课默认不允许）。遇使用：查找，失败则未声明。记录指针写回 AST 节点，后续不再比字符串。<span class="marginnote">数字实例：<code>{ int x = 1; { double x = 2.0; /* 这里查到 2.0 */ } /* 这里又查回 1 */ }</code>——查找从栈顶逐层问「这层有没有 x」，第一个答「有」的就是绑定；两层同名不报错，同层同名才报重复声明。</span></p>',11)),(o(),E(n,null,{default:s(()=>[i(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20USE%5B%22%E4%BD%BF%E7%94%A8%20x%22%5D%20--%3E%20LOOK%5B%22%E4%BB%8E%E5%86%85%E5%B1%82%E5%90%91%E5%A4%96%E6%9F%A5%22%5D%0A%20%20LOOK%20--%3E%20BIND%5B%22%E7%BB%91%E5%AE%9A%E5%88%B0%E5%A3%B0%E6%98%8E%22%5D%0A%20%20LOOK%20--%3E%20ERR%5B%22%E6%9C%AA%E5%A3%B0%E6%98%8E%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"模块导入、命名空间是多层中的横向边，本课点名：仍是查找路径，不是新的图算法。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,[e("编译期符号表不必留到运行时；调试信息可以。运行时栈帧布局在 ABI 课按记录的偏移填。"),t("a",{href:"/cs/riscv-int-isa"},"RISC-V 寄存器"),e("还没选，偏移可以先按抽象槽。同名函数重载要带类型键，留给类型课。")],-1)),(o(),E(n,null,{default:s(()=>[i(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%B1%82%200%EF%BC%9A%E5%85%A8%E5%B1%80%20int%20x%20%3D%201%22%5D%20--%3E%20F%5B%22%E5%B1%82%201%EF%BC%9A%E5%87%BD%E6%95%B0%E4%BD%93%20double%20x%20%3D%202.0%22%5D%0A%20%20F%20--%3E%20B%5B%22%E5%B1%82%202%EF%BC%9A%E5%9D%97%E5%86%85%20char%20x%20%3D%20'a'%22%5D%0A%20%20B%20--%3E%20U%7B%22%E5%9D%97%E5%86%85%E7%94%A8%20x%EF%BC%9A%E7%BB%91%E5%88%B0%E8%B0%81%3F%22%7D%0A%20%20U%20--%3E%7C%22%E5%B1%82%202%20%E5%91%BD%E4%B8%AD%22%7C%20HIT%5B%22%E7%BB%91%E5%88%B0%20char%20x%EF%BC%9A%E9%81%AE%E8%94%BD%E5%8F%91%E7%94%9F%22%5D%0A%20%20U%20--%3E%7C%22%E5%9D%97%E7%BB%93%E6%9D%9F%EF%BC%8C%E5%BC%B9%E6%8E%89%E5%B1%82%202%22%7C%20U2%7B%22%E5%86%8D%E7%94%A8%20x%22%7D%0A%20%20U2%20--%3E%20HIT2%5B%22%E7%BB%91%E5%88%B0%20double%20x%EF%BC%9A%E5%B1%82%201%20%E5%91%BD%E4%B8%AD%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">初学者容易把词法作用域与动态作用域混为一谈：前者看「源代码里谁包着谁」，编译期就定死；后者看「运行时谁调用了谁」，同一行代码每次调用可能绑到不同的 x。本栏默认前者，静态链就是词法嵌套留在运行时的影子。</span></p><p>宏与卫生宏会打乱「源里看见的名字」，本课不处理。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不检查类型、不做隐式转换、不解析方法分派（虚表是后话）。不处理链接期的全局符号解析——那是<a href="/cs/link-reloc">链接</a>的另一张表。后课默认：AST 上的名字已绑到声明。类型是否合法是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>词法作用域 = 嵌套层叠；内层遮蔽外层。</li><li>符号表实现查找；绑定写回 AST。</li><li>未声明与重复声明在本课报告。</li><li>出处：Aho et al., 龙书第 2、6 章。</li></ul>',6))])}const _=B(c,[["render",A]]);export{b as __pageData,_ as default};
